106→<script>
107→(function () {
108→  // Wait for app embed to set window.__zccAppEnabled.
109→  // App embed (target: body) may load after this section block, so we poll briefly.
110→  var maxWait = 3000; // ms
111→  var interval = 50;  // ms
112→  var elapsed = 0;
113→
114→  function tryInit() {
115→    if (window.__zccAppEnabled) {
116→      init();
117→    } else if (elapsed < maxWait) {
118→      elapsed += interval;
119→      setTimeout(tryInit, interval);
120→    }
121→    // If app embed is not enabled after 3s, do nothing (merchant hasn't enabled it)
122→  }
123→
124→  // Start checking — if already set, runs immediately
125→  if (document.readyState === 'loading') {
126→    document.addEventListener('DOMContentLoaded', tryInit);
127→  } else {
128→    tryInit();
129→  }
130→
131→  function init() {
132→  var ROOT_ID = "zcc-widget-{{ block.id }}";
133→  var container = document.getElementById(ROOT_ID);
134→  if (!container) return;
135→
136→  var SHOP = container.dataset.shop;
137→  // app.url resolves to the App Proxy URL (e.g. https://store.myshopify.com/apps/zipcheck).
138→  // If for any reason it is empty (e.g. dev environment or Shopify Liquid context issue),
139→  // fall back to the relative proxy path so the request still routes correctly through
140→  // Shopify's App Proxy rather than hitting the store's own domain as a missing route.
141→  var _rawApi = (container.dataset.api || "").replace(/\/$/, "");
142→  var _proxyPath = (container.dataset.proxy || "/apps/zipcheck").replace(/\/$/, "");
143→  // Prefer app.url when it looks like a full URL; otherwise use the relative proxy path
144→  // (which Shopify will forward to our app via the App Proxy config).
145→  var API_BASE = (_rawApi && _rawApi.indexOf("http") === 0) ? _rawApi : _proxyPath;
146→
147→  // ── Pre-lock: applied synchronously BEFORE the async config fetch ────────────
148→  // This eliminates the race window where ATC/Buy Now buttons are clickable
149→  // while the config fetch is in flight (typically 100–500 ms).
150→  // renderWidget() will call _zccUnlock() immediately if the feature is
151→  // disabled (lockButtonsUntilZipCheck:false) or position is "inline".
152→  var _zccLockStyleId = 'zcc-lock-style';
153→  function _zccInjectLockCss() {
154→    if (document.getElementById(_zccLockStyleId)) return;
155→    var s = document.createElement('style');
156→    s.id = _zccLockStyleId;
157→    s.textContent =
158→      'html[data-zcc-locked] form[action*="/cart/add"] button[type="submit"],' +
159→      'html[data-zcc-locked] button[name="add"],' +
160→      'html[data-zcc-locked] .product-form__submit,' +
161→      'html[data-zcc-locked] [data-product-add],' +
162→      'html[data-zcc-locked] .btn--add-to-cart,' +
163→      'html[data-zcc-locked] .product-form button[type="submit"],' +
164→      'html[data-zcc-locked] button.product-form__cart-submit,' +
165→      'html[data-zcc-locked] .product__submit button[type="submit"],' +
166→      'html[data-zcc-locked] .pdp-form button[type="submit"]' +
167→      '{opacity:.4!important;pointer-events:none!important;cursor:not-allowed!important;}' +
168→      'html[data-zcc-locked] .shopify-payment-button,' +
169→      'html[data-zcc-locked] [data-shopify="payment-button"],' +
170→      'html[data-zcc-locked] .shopify-payment-button__button--unbranded' +
171→      '{position:relative!important;opacity:.4!important;pointer-events:none!important;cursor:not-allowed!important;}' +
172→      'html[data-zcc-locked] .shopify-payment-button::after,' +
173→      'html[data-zcc-locked] [data-shopify="payment-button"]::after' +
174→      '{content:""!important;position:absolute!important;inset:0!important;z-index:2147483647!important;cursor:not-allowed!important;background:transparent!important;}';
175→    (document.head || document.documentElement).appendChild(s);
176→  }
177→  function _zccLock() {
178→    _zccInjectLockCss();
179→    document.documentElement.setAttribute('data-zcc-locked', '1');
180→  }
181→  function _zccUnlock() {
182→    document.documentElement.removeAttribute('data-zcc-locked');
183→  }
184→  // Lock immediately — but skip if the customer already validated this shop's
185→  // ZIP in this session (avoids flash-of-disabled-buttons on page refresh).
186→  var _priorValid = false;
187→  try {
188→    _priorValid = sessionStorage.getItem('zcc:valid') === 'true' &&
189→                  sessionStorage.getItem('zcc:shop') === SHOP;
190→  } catch(e) {}
191→  if (!_priorValid) {
192→    _zccLock();
193→  }
194→
195→  // Always fetch fresh config from the API so color/setting changes made in the
196→  // admin are reflected on the storefront immediately. The metafield-embedded
197→  // data-config attribute is intentionally ignored here: it is baked into
198→  // Shopify's CDN-cached HTML at render time and can be stale for many minutes
199→  // after a merchant saves new settings. The API endpoint returns
200→  // Cache-Control: no-store so it is always up to date.
201→  fetch(API_BASE + "/api/widget-config?shop=" + encodeURIComponent(SHOP))
202→    .then(function (r) {
203→      if (!r.ok) throw new Error("Widget config API returned " + r.status);
204→      return r.json();
205→    })
206→    .then(function (cfg) { renderWidget(cfg); })
207→    .catch(function (err) {
208→      console.warn("[Pinzo] Could not load widget config, using defaults:", err.message || err);
209→      renderWidget({});
210→    });
211→
212→  function renderWidget(cfg) {
213→    // Merge with defaults
214→    var D = {
215→      position: "inline",
216→      heading: "Check Delivery Availability",
217→      placeholder: "Enter your zip code",
218→      buttonText: "Check",
219→      successMessage: "Great news! We deliver to your area.",
220→      errorMessage: "Sorry, we don\u2019t deliver to this area yet.",
221→      notFoundMessage: "We currently do not ship to this ZIP code.",
222→      primaryColor: "#008060",
223→      successColor: "#008060",
224→      errorColor: "#D72C0D",
225→      backgroundColor: "#FFFFFF",
226→      textColor: "#202223",
227→      borderRadius: "8",
228→      showEta: true,
229→      showZone: false,
230→      showWaitlistOnFailure: false,
231→      showCod: true,
232→      showReturnPolicy: true,
233→      showCutoffTime: true,
234→      showDeliveryDays: true,
235→      showDeliveryDate: true,
236→      showCountdown: true,
237→      showDeliveryFee: true,
238→      customCss: "",
239→      blockCartOnInvalid: false,
240→      showSocialProof: true,
241→    };
242→    // Default lockButtonsUntilZipCheck to true
243→    if (cfg.lockButtonsUntilZipCheck === undefined || cfg.lockButtonsUntilZipCheck === null) {
244→      cfg.lockButtonsUntilZipCheck = true;
245→    }
246→    Object.keys(D).forEach(function (k) {
247→      if (cfg[k] === undefined || cfg[k] === null) cfg[k] = D[k];
248→    });
249→

250→    // Release pre-lock if feature is disabled OR widget is inline
251→    // (inline widget is directly visible — customer doesn't need to hunt for it)
252→    if (!cfg.lockButtonsUntilZipCheck || cfg.position === 'inline') {
253→      _zccUnlock();
254→    }
255→
256→    var rad = cfg.borderRadius + "px";
257→    var WID = "zcc-" + ROOT_ID;
258→
259→    if (cfg.position === "floating") {
260→      renderFloating(cfg, WID, rad);
261→    } else if (cfg.position === "popup") {
262→      renderPopup(cfg, WID, rad);
263→    } else {
264→      renderInline(cfg, WID, rad);
265→    }
266→
267→    // If blockCartOnInvalid is enabled, disable ATC/Buy Now buttons on page load
268→    // until the customer validates their ZIP code
269→    if (cfg.blockCartOnInvalid) {
270→      blockCartButtonsInitial();
271→    }
272→
273→    // If lockButtonsUntilZipCheck is enabled AND the widget is in floating or popup mode,
274→    // disable ATC/Buy Now buttons until the customer successfully validates their ZIP code.
275→    // This is separate from blockCartOnInvalid (which also re-blocks on invalid).
276→    // lockButtonsUntilZipCheck only activates in non-inline modes (floating/popup) because
277→    // in those modes the widget is not directly visible on the product page by default.
278→    if (cfg.lockButtonsUntilZipCheck && (cfg.position === "floating" || cfg.position === "popup")) {
279→      lockAtcButtonsForZipCheck();
280→    }
281→  }
282→
283→  // ── Block ATC buttons on page load (before any ZIP check) ─────────────────
284→  function blockCartButtonsInitial() {
285→    var ATC_SELECTORS = [
286→      'button[name="add"]',
287→      '.product-form__submit',
288→      '[data-product-add]',
289→      '.btn--add-to-cart',
290→      '.product-form button[type="submit"]',
291→      'button.shopify-payment-button__button',
292→      '.shopify-payment-button button',
293→      'button.product-form__cart-submit'
294→    ].join(',');
295→
296→    function doBlock() {
297→      try {
298→        var atcBtns = document.querySelectorAll(ATC_SELECTORS);
299→        atcBtns.forEach(function(b) {
300→          if (!b.closest('[data-zcc-widget]')) {
301→            if (!b.getAttribute('data-zcc-blocked')) {
302→              b.setAttribute('data-zcc-orig-title', b.title || '');
303→            }
304→            b.disabled = true;
305→            b.style.opacity = '0.5';
306→            b.title = 'Please check ZIP code availability first';
307→            b.setAttribute('data-zcc-blocked', 'true');
308→          }
309→        });
310→      } catch(e) {}
311→    }
312→
313→    // Block immediately + delays for dynamic buttons (Shopify Buy Now renders late)
314→    doBlock();
315→    setTimeout(doBlock, 500);
316→    setTimeout(doBlock, 1500);
317→
318→    // MutationObserver for dynamic payment buttons
319→    if (typeof MutationObserver !== 'undefined') {
320→      var observer = new MutationObserver(function() { doBlock(); });
321→      var form = document.querySelector('.product-form, [data-product-form], form[action*="/cart/add"]');
322→      if (form) {
323→        observer.observe(form, { childList: true, subtree: true });
324→        setTimeout(function() { observer.disconnect(); }, 10000);
325→      }
326→    }
327→  }
328→
329→  // ── Wire up lock/unlock listeners (floating/popup mode) ─────────────────────
330→  // Pre-lock is already applied synchronously above via _zccLock().
331→  // This function wires up zcc:validated so buttons unlock on success.
332→  function lockAtcButtonsForZipCheck() {
333→    // Start in the correct state — if the customer already validated, treat as verified.
334→    var zipVerified = _priorValid;
335→
336→    window.addEventListener('zcc:validated', function(e) {
337→      var detail = e.detail;
338→      if (detail && detail.valid === true) {
339→        zipVerified = true;
340→        _zccUnlock();
341→      } else if (detail && detail.valid === false) {
342→        zipVerified = false;
343→        _zccLock();
344→      }
345→    });
346→
347→    // Re-lock if customer edits ZIP field after a successful check
348→    document.addEventListener('input', function(e) {
349→      var t = e.target;
350→      if (t && t.classList && t.classList.contains('zcc-input') && zipVerified) {
351→        zipVerified = false;
352→        _zccLock();
353→      }
354→    });
355→  }
356→
357→  // ── Scope custom CSS: auto-prefix selectors with widget container ID ──────
358→  function scopeCustomCss(rawCss, wid) {
359→    if (!rawCss) return "";
360→    // Strip </style> tags to prevent injection
361→    var css = rawCss.replace(/<\/style>/gi, "");
362→    var result = "";
363→    var i = 0;
364→    while (i < css.length) {
365→      // Skip whitespace
366→      while (i < css.length && /\s/.test(css[i])) { result += css[i]; i++; }
367→      if (i >= css.length) break;
368→      // Pass through @keyframes and @font-face unchanged
369→      if (css[i] === '@') {
370→        var atRule = "";
371→        var j = i;
372→        while (j < css.length && css[j] !== '{' && css[j] !== ';') { atRule += css[j]; j++; }
373→        var atName = atRule.trim().toLowerCase();
374→        if (atName.indexOf("@keyframes") === 0 || atName.indexOf("@font-face") === 0) {
375→          result += atRule;
376→          if (j < css.length && css[j] === '{') {
377→            var depth = 1; result += css[j]; j++;
378→            while (j < css.length && depth > 0) {
379→              if (css[j] === '{') depth++;
380→              if (css[j] === '}') depth--;
381→              result += css[j]; j++;
382→            }
383→          }
384→          i = j; continue;
385→        }
386→        // @media: scope inner rules
387→        if (atName.indexOf("@media") === 0) {
388→          result += atRule;
389→          if (j < css.length && css[j] === '{') {
390→            result += '{'; j++;
391→            // Collect inner content
392→            var depth = 1; var inner = "";
393→            while (j < css.length && depth > 0) {
394→              if (css[j] === '{') depth++;
395→              if (css[j] === '}') depth--;
396→              if (depth > 0) inner += css[j];
397→              j++;
398→            }
399→            result += scopeCustomCss(inner, wid);

400→            result += '}';
401→          }
402→          i = j; continue;
403→        }
404→      }
405→      // Regular rule: grab selector, prefix with #wid
406→      var sel = ""; var body = "";
407→      while (i < css.length && css[i] !== '{') { sel += css[i]; i++; }
408→      if (i < css.length) { i++; } // skip {
409→      var depth = 1;
410→      while (i < css.length && depth > 0) {
411→        if (css[i] === '{') depth++;
412→        if (css[i] === '}') depth--;
413→        if (depth > 0) body += css[i];
414→        i++;
415→      }
416→      if (sel.trim()) {
417→        // Split multiple selectors by comma and prefix each
418→        var selectors = sel.split(',').map(function(s) {
419→          s = s.trim();
420→          if (!s) return '';
421→          return '#' + wid + ' ' + s;
422→        }).filter(Boolean).join(', ');
423→        result += selectors + ' {' + body + '}';
424→      }
425→    }
426→    return result;
427→  }
428→
429→  // ── Delivery date formatter ───────────────────────────────────────────────────
430→  function formatDeliveryDate(isoDate) {
431→    if (!isoDate) return null;
432→    try {
433→      var parts = isoDate.split('-');
434→      var d = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]));
435→      var days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
436→      var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
437→      return days[d.getDay()] + ', ' + months[d.getMonth()] + ' ' + d.getDate();
438→    } catch(e) { return null; }
439→  }
440→
441→  // ── Countdown timer functions ─────────────────────────────────────────────────
442→  function getCountdownData(cutoffTime) {
443→    if (!cutoffTime) return null;
444→    var parts = cutoffTime.split(':');
445→    var cutoffHr = parseInt(parts[0], 10);
446→    var cutoffMin = parseInt(parts[1] || '0', 10);
447→    var now = new Date();
448→    var cutoff = new Date();
449→    cutoff.setHours(cutoffHr, cutoffMin, 0, 0);
450→    var diff = cutoff - now;
451→    if (diff <= 0) return { passed: true, hours: 0, minutes: 0 };
452→    var hours = Math.floor(diff / 3600000);
453→    var minutes = Math.floor((diff % 3600000) / 60000);
454→    return { passed: false, hours: hours, minutes: minutes };
455→  }
456→
457→  function buildCountdownHtml(cutoffTime, widgetId) {
458→    var cd = getCountdownData(cutoffTime);
459→    if (!cd) return '';
460→    var colorClass, text;
461→    if (cd.passed) {
462→      colorClass = 'zcc-countdown--passed';
463→      text = 'Order now for next business day dispatch';
464→    } else {
465→      var totalMinutes = cd.hours * 60 + cd.minutes;
466→      if (totalMinutes > 180) colorClass = 'zcc-countdown--green';
467→      else if (totalMinutes > 60) colorClass = 'zcc-countdown--amber';
468→      else colorClass = 'zcc-countdown--red';
469→      text = 'Order within <strong>' + cd.hours + 'h ' + cd.minutes + 'm</strong> for same-day dispatch';
470→    }
471→    return '<div class="zcc-countdown ' + colorClass + '" id="' + widgetId + '-countdown">' + ICONS.clock + '<span>' + text + '</span></div>';
472→  }
473→
474→  function startCountdownUpdater(widgetId, cutoffTime) {
475→    if (!cutoffTime) return;
476→    setInterval(function() {
477→      var el = document.getElementById(widgetId + '-countdown');
478→      if (!el) return;
479→      var cd = getCountdownData(cutoffTime);
480→      if (!cd) return;
481→      if (cd.passed) {
482→        el.className = 'zcc-countdown zcc-countdown--passed';
483→        el.innerHTML = ICONS.clock + '<span>Order now for next business day dispatch</span>';
484→        return;
485→      }
486→      var totalMinutes = cd.hours * 60 + cd.minutes;
487→      var cls = totalMinutes > 180 ? 'zcc-countdown--green' : totalMinutes > 60 ? 'zcc-countdown--amber' : 'zcc-countdown--red';
488→      el.className = 'zcc-countdown ' + cls;
489→      el.innerHTML = ICONS.clock + '<span>Order within <strong>' + cd.hours + 'h ' + cd.minutes + 'm</strong> for same-day dispatch</span>';
490→    }, 30000);
491→  }
